# Python approach using requests (may need session cookies)
import requests

def get_tipranks_consensus(ticker):
    """Fetch analyst consensus from TipRanks internal API.
    NOTE: These endpoints may require browser-like headers and may break.
    Use the tipranks npm/python libraries for more reliable access."""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Accept': 'application/json'
    }

    # Price targets
    pt_url = f'https://www.tipranks.com/api/stocks/getPriceTargets/?ticker={ticker}'
    try:
        resp = requests.get(pt_url, headers=headers, timeout=10)
        if resp.status_code == 200:
            return resp.json()
    except Exception as e:
        print(f'TipRanks blocked: {e}')
    return None

